function computeBestStartDP(A, k) {
  const n = A.length;
  const pref = Array(n+1).fill(0);
  for (let i=0;i<n;i++) pref[i+1] = pref[i] + A[i];
  const bestStart = Array.from({length:n}, ()=> Array(n).fill(-Infinity));
  for (let l=0; l<n; l++) {
    let best = -Infinity;
    for (let i=l; i<n; i++) {
      const sum = pref[i+1]-pref[l];
      best = Math.max(best, sum);
      bestStart[l][i] = best;
    }
  }
  const dp = Array.from({length:n}, ()=> Array(k+1).fill(-Infinity));
  const par = Array.from({length:n}, ()=> Array(k+1).fill(-1));
  for (let i=0; i<n; i++) dp[i][1] = bestStart[0][i];
  for (let t=2; t<=k; t++) {
    for (let i=t-1; i<n; i++) {
      let bestVal = -Infinity, bestL = -1;
      for (let l=t-1; l<=i; l++) {
        const prev = (l-1>=0) ? dp[l-1][t-1] : (t-1===0 ? 0 : -Infinity);
        const val = prev + bestStart[l][i];
        if (val > bestVal) { bestVal = val; bestL = l; }
      }
      dp[i][t] = bestVal;
      par[i][t] = bestL;
    }
  }
  return {dp, par};
}
```

## Follow-up Questions
- How would you optimize space to O(nk)?
- How would you reconstruct the exact endpoints efficiently?

## Why This Is Asked
This problem tests the ability to model selections of multiple disjoint subarrays with an exact count — a common dynamic programming pattern in interviews.

## Key Concepts
- **DP on prefix**: State dp[i][t] tracks the best total using the first i elements with exactly t subarrays
- **Prefix sums**: Enable O(1) calculation of any subarray sum
- **Backpointers**: Store decisions to reconstruct the chosen subarrays
- **Edge cases**: Handle when n < k or when all values are negative

## Code Example
```javascript
function maxKSubarrays(A, k) {
  const n = A.length;
  const pref = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) pref[i] = pref[i - 1] + A[i - 1];

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const prev = Array.from({ length: n + 1 }, () => Array(k + 1).fill(null));
  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 0; t <= k; t++) {
      if (dp[i - 1][t] >= dp[i][t]) {
        dp[i][t] = dp[i - 1][t];
        prev[i][t] = { skip: true };
      }
      for (let l = 1; l <= i; l++) {
        if (t > 0 && dp[l - 1][t - 1] !== -Infinity) {
          const val = dp[l - 1][t - 1] + (pref[i] - pref[l - 1]);
          if (val > dp[i][t]) {
            dp[i][t] = val;
            prev[i][t] = { skip: false, l, t: t - 1 };
          }
        }
      }
    }
  }

  const result = [];
  let i = n, t = k;
  while (i > 0 && t > 0) {
    const p = prev[i][t];
    if (p.skip) { i--; continue; }
    result.push([p.l, i]);
    i = p.l - 1; t = p.t;
  }
  return { value: dp[n][k], subarrays: result.reverse() };
}
```
